class FourDirectionalMaxSumPath {
  private int[][] grid;
  private int bestSum;
  private Set<String> seen;
  private int R, C;

  private void visit(int r, int c, int pathSum) {
    // Process leaf/full solution
    if (r == R - 1 && c == C - 1) {
      if (pathSum > bestSum) {
        bestSum = pathSum;
      }
      return;
    }

    // Try each direction
    int[][] directions = { { 0, 1 }, { 1, 0 }, { 0, -1 }, { -1, 0 } };
    for (int[] dir : directions) {
      int nr = r + dir[0];
      int nc = c + dir[1];
      String key = nr + "," + nc;
      if (!seen.contains(key) && nr >= 0 && nr < R && nc >= 0 && nc < C) {
        seen.add(key);
        visit(nr, nc, pathSum + grid[nr][nc]);
        seen.remove(key);
      }
    }
  }

  public int solve(int[][] inputGrid) {
    grid = inputGrid;
    R = grid.length;
    C = grid[0].length;
    bestSum = Integer.MIN_VALUE;
    seen = new HashSet<>();
    seen.add("0,0");

    // Start from top-left
    visit(0, 0, grid[0][0]);
    return bestSum;
  }
}

